package handlers

import "testing"

func TestParseVersion(t *testing.T) {
	for _, version := range []string{"1.2.3", "0.0.0-dev"} {
		if got := parseVersion(version); got == "" {
			t.Errorf("parseVersion(%q) returned empty", version)
		}
	}
}

